7	// registerStringBuiltins registers string manipulation functions
8	func registerStringBuiltins() {
9		// len_str(s: string) -> int
10		// Returns the length of a string
11		Register(BuiltinDef{
12			Name:           "len_str",
13			ParamTypeNames: []string{"string"},
14			ReturnTypeName: "int",
15			Impl: func(args ...interface{}) interface{} {
16				if len(args) == 0 {
17					return 0
18				}
19				s, ok := args[0].(string)
20				if !ok {
21					return 0
22				}
23				return len(s)
24			},
25		})
26	
27		// concat(a: string, b: string) -> string
28		// Concatenates two strings
29		Register(BuiltinDef{
30			Name:           "concat",
31			ParamTypeNames: []string{"string", "string"},
32			ReturnTypeName: "string",
33			Impl: func(args ...interface{}) interface{} {
34				if len(args) < 2 {
35					return ""
36				}
37				a, ok1 := args[0].(string)
38				b, ok2 := args[1].(string)
39				if !ok1 || !ok2 {
40					return ""
41				}
42				return a + b
43			},
44		})
45	
46		// substring(s: string, start: int, end: int) -> string
47		// Returns a substring from start to end (exclusive)
48		Register(BuiltinDef{
49			Name:           "substring",
50			ParamTypeNames: []string{"string", "int", "int"},
51			ReturnTypeName: "string",
52			Impl: func(args ...interface{}) interface{} {
53				if len(args) < 3 {
54					return ""
55				}
56				s, ok1 := args[0].(string)
57				start, ok2 := args[1].(int)
58				end, ok3 := args[2].(int)
59				if !ok1 || !ok2 || !ok3 {
60					return ""
61				}
62				if start < 0 || end > len(s) || start > end {
63					return ""
64				}
65				return s[start:end]
66			},
67		})
68	
69		// upper(s: string) -> string
70		// Converts string to uppercase
71		Register(BuiltinDef{
72			Name:           "upper",
73			ParamTypeNames: []string{"string"},
74			ReturnTypeName: "string",
75			Impl: func(args ...interface{}) interface{} {
76				if len(args) == 0 {
77					return ""
78				}
79				s, ok := args[0].(string)
80				if !ok {
81					return ""
82				}
83				return strings.ToUpper(s)
84			},
85		})
86	
87		// lower(s: string) -> string
88		// Converts string to lowercase
89		Register(BuiltinDef{
90			Name:           "lower",
91			ParamTypeNames: []string{"string"},
92			ReturnTypeName: "string",
93			Impl: func(args ...interface{}) interface{} {
94				if len(args) == 0 {
95					return ""
96				}
97				s, ok := args[0].(string)
98				if !ok {
99					return ""
100				}
101				return strings.ToLower(s)
102			},
103		})
104	
105		// split(s: string, sep: string) -> string[]
106		// Splits a string by separator
107		Register(BuiltinDef{
108			Name:           "split",
109			ParamTypeNames: []string{"string", "string"},
110			ReturnTypeName: "string", // simplified: would be array in full implementation
111			Impl: func(args ...interface{}) interface{} {
112				if len(args) < 2 {
113					return []string{}
114				}
115				s, ok1 := args[0].(string)
116				sep, ok2 := args[1].(string)
117				if !ok1 || !ok2 {
118					return []string{}
119				}
120				return strings.Split(s, sep)
121			},
122		})
123	}
