3	// registerArrayBuiltins registers array manipulation functions
4	func registerArrayBuiltins() {
5		// len_arr(arr: array) -> int
6		// Returns the length of an array
7		Register(BuiltinDef{
8			Name:           "len_arr",
9			ParamTypeNames: []string{"any"}, // array type
10			ReturnTypeName: "int",
11			Impl: func(args ...interface{}) interface{} {
12				if len(args) == 0 {
13					return 0
14				}
15				// Handle []interface{} type
16				switch v := args[0].(type) {
17				case []interface{}:
18					return len(v)
19				case []int:
20					return len(v)
21				case []string:
22					return len(v)
23				default:
24					return 0
25				}
26			},
27		})
28	
29		// append(arr: array, value: any) -> array
30		// Appends a value to an array
31		Register(BuiltinDef{
32			Name:           "append",
33			ParamTypeNames: []string{"any", "any"},
34			ReturnTypeName: "any",
35			Impl: func(args ...interface{}) interface{} {
36				if len(args) < 2 {
37					return []interface{}{}
38				}
39				// Handle []interface{} type
40				arr, ok := args[0].([]interface{})
41				if !ok {
42					return []interface{}{args[1]}
43				}
44				return append(arr, args[1])
45			},
46		})
47	
48		// get(arr: array, index: int) -> any
49		// Gets element at index from array
50		Register(BuiltinDef{
51			Name:           "get",
52			ParamTypeNames: []string{"any", "int"},
53			ReturnTypeName: "any",
54			Impl: func(args ...interface{}) interface{} {
55				if len(args) < 2 {
56					return nil
57				}
58				arr, ok1 := args[0].([]interface{})
59				idx, ok2 := args[1].(int)
60				if !ok1 || !ok2 {
61					return nil
62				}
63				if idx < 0 || idx >= len(arr) {
64					return nil
65				}
66				return arr[idx]
67			},
68		})
69	
70		// set(arr: array, index: int, value: any) -> void
71		// Sets element at index in array
72		Register(BuiltinDef{
73			Name:           "set",
74			ParamTypeNames: []string{"any", "int", "any"},
75			ReturnTypeName: "unit",
76			Impl: func(args ...interface{}) interface{} {
77				if len(args) < 3 {
78					return nil
79				}
80				arr, ok1 := args[0].([]interface{})
81				idx, ok2 := args[1].(int)
82				if !ok1 || !ok2 {
83					return nil
84				}
85				if idx < 0 || idx >= len(arr) {
86					return nil
87				}
88				arr[idx] = args[2]
89				return nil
90			},
91		})
92	
93		// slice(arr: array, start: int, end: int) -> array
94		// Returns a slice of the array from start to end (exclusive)
95		Register(BuiltinDef{
96			Name:           "slice",
97			ParamTypeNames: []string{"any", "int", "int"},
98			ReturnTypeName: "any",
99			Impl: func(args ...interface{}) interface{} {
100				if len(args) < 3 {
101					return []interface{}{}
102				}
103				arr, ok1 := args[0].([]interface{})
104				start, ok2 := args[1].(int)
105				end, ok3 := args[2].(int)
106				if !ok1 || !ok2 || !ok3 {
107					return []interface{}{}
108				}
109				if start < 0 || end > len(arr) || start > end {
110					return []interface{}{}
111				}
112				return arr[start:end]
113			},
114		})
115	}
