1	// Package ir implements IR generation from optimized AST
2	package ir
3	
4	import (
5		"fmt"
6	
7		"github.com/user/freelang-evolving-compiler/internal/ast"
8	)
9	
10	// Generator converts AST to intermediate representation
11	type Generator struct {
12		tempCount    int
13		labelCount   int
14		currentFn    *Function
15		program      *Program
16		structFields map[string][]string
17	}
18	
19	// NewGenerator creates a new IR generator
20	func NewGenerator() *Generator {
21		return &Generator{
22			tempCount:  0,
23			labelCount: 0,
24			program: &Program{
25				Functions: []Function{},
26				Main:      []Instruction{},
27			},
28			structFields: make(map[string][]string),
29		}
30	}
31	
32	// Generate converts an AST to an IR program
33	func (g *Generator) Generate(root *ast.Node) (*Program, error) {
34		if root == nil {
35			return g.program, nil
36		}
37	
38		// Process program statements
39		if root.Kind == ast.NodeProgram {
40			for _, child := range root.Children {
41				if child.Kind == ast.NodeFnDecl {
42					if err := g.genFnDecl(child); err != nil {
43						return nil, err
44					}
45				} else if child.Kind == ast.NodeStructDecl {
46					if err := g.genStructDecl(child); err != nil {
47						return nil, err
48					}
49				} else {
50					if err := g.genStmt(child); err != nil {
51						return nil, err
52					}
53				}
54			}
55		} else {
56			if err := g.genStmt(root); err != nil {
57				return nil, err
58			}
59		}
60	
61		return g.program, nil
62	}
63	
64	// genFnDecl generates IR for a function declaration
65	func (g *Generator) genFnDecl(node *ast.Node) error {
66		if len(node.Children) < 2 {
67			return fmt.Errorf("function declaration must have name and body")
68		}
69	
70		fnName := node.Children[0].Value
71		body := node.Children[len(node.Children)-1]
72	
73		fn := Function{
74			Name:   fnName,
75			Params: []string{},
76			Body:   []Instruction{},
77		}
78	
79		// Extract parameter names if they exist
80		if len(node.Children) > 2 {
81			for i := 1; i < len(node.Children)-1; i++ {
82				if node.Children[i].Kind == ast.NodeIdent {
83					fn.Params = append(fn.Params, node.Children[i].Value)
84				}
85			}
86		}
87	
88		// Save current function and switch context
89		prevFn := g.currentFn
90		g.currentFn = &fn
91	
92		// Generate OpEnter
93		g.emit(Instruction{Op: OpEnter, Fn: fnName})
94	
95		// Generate body
96		if body.Kind == ast.NodeBlockStmt {
97			for _, stmt := range body.Children {
98				if err := g.genStmt(stmt); err != nil {
99					return err
100				}
101			}
102		} else {
103			if err := g.genStmt(body); err != nil {
104				return err
105			}
106		}
107	
108		// Generate OpLeave if not already there
109		g.emit(Instruction{Op: OpLeave, Fn: fnName})
110	
111		// Add function to program
112		g.program.Functions = append(g.program.Functions, fn)
113		g.currentFn = prevFn
114	
115		return nil
116	}
117	
118	// genStmt generates IR for a statement
119	func (g *Generator) genStmt(node *ast.Node) error {
120		if node == nil {
121			return nil
122		}
123	
124		switch node.Kind {
125		case ast.NodeLetDecl:
126			return g.genLetDecl(node)
127		case ast.NodeIfStmt:
128			return g.genIfStmt(node)
129		case ast.NodeForStmt:
130			return g.genForStmt(node)
131		case ast.NodeReturn:
132			return g.genReturn(node)
133		case ast.NodeStructDecl:
134			return g.genStructDecl(node)
135		case ast.NodeBlockStmt:
136			for _, child := range node.Children {
137				if err := g.genStmt(child); err != nil {
138					return err
139				}
140			}
141			return nil
142		default:
143			// Expression statement
144			_, err := g.genExpr(node)
145			return err
146		}
147	}
148	
149	// genLetDecl generates IR for a let declaration
150	func (g *Generator) genLetDecl(node *ast.Node) error {
151		if len(node.Children) < 2 {
152			return fmt.Errorf("let declaration must have name and value")
153		}
154	
155		varName := node.Children[0].Value
156		valueExpr := node.Children[1]
157	
158		// Generate code for the expression
159		operand, err := g.genExpr(valueExpr)
160		if err != nil {
161			return err
162		}
163	
164		// Copy result to variable
165		g.emit(Instruction{
166			Op:   OpCopy,
167			Dest: Operand{Name: varName},
168			Src1: operand,
169		})
170	
171		return nil
172	}
173	
174	// genIfStmt generates IR for an if statement
175	func (g *Generator) genIfStmt(node *ast.Node) error {
176		if len(node.Children) < 2 {
177			return fmt.Errorf("if statement must have condition and body")
178		}
179	
180		condExpr := node.Children[0]
181		bodyStmt := node.Children[1]
182	
183		// Generate condition
184		condOp, err := g.genExpr(condExpr)
185		if err != nil {
186			return err
187		}
188	
189		// Create end label
190		endLabel := g.newLabel("end")
191	
192		// Jump if false
193		g.emit(Instruction{
194			Op:    OpJumpIfFalse,
195			Src1:  condOp,
196			Label: endLabel,
197		})
198	
199		// Generate body
200		if err := g.genStmt(bodyStmt); err != nil {
201			return err
202		}
203	
204		// Emit end label
205		g.emit(Instruction{
206			Op:    OpLabel,
207			Label: endLabel,
208		})
209	
210		return nil
211	}
212	
213	// genForStmt generates IR for a for statement
214	func (g *Generator) genForStmt(node *ast.Node) error {
215		if len(node.Children) < 3 {
216			return fmt.Errorf("for statement must have iterator, range, and body")
217		}
218	
219		iterName := node.Children[0].Value
220		rangeExpr := node.Children[1]
221		bodyStmt := node.Children[2]
222	
223		// Extract range start and end
224		if rangeExpr.Kind != ast.NodeBinaryExpr || rangeExpr.Value != ".." {
225			return fmt.Errorf("for loop requires range expression (..)")
226		}
227	
228		if len(rangeExpr.Children) < 2 {
229			return fmt.Errorf("range expression requires start and end")
230		}
231	
232		startOp, err := g.genExpr(rangeExpr.Children[0])
233		if err != nil {
234			return err
235		}
236	
237		endOp, err := g.genExpr(rangeExpr.Children[1])
238		if err != nil {
239			return err
240		}
241	
242		// Initialize iterator
243		g.emit(Instruction{
244			Op:   OpCopy,
245			Dest: Operand{Name: iterName},
246			Src1: startOp,
247		})
248	
249		// Create loop and end labels
250		loopLabel := g.newLabel("loop")
251		endLabel := g.newLabel("end")
252	
253		// Emit loop label
254		g.emit(Instruction{
255			Op:    OpLabel,
256			Label: loopLabel,
257		})
258	
259		// Check condition: iterator < end
260		cmpTemp := g.newTemp()
261		g.emit(Instruction{
262			Op:   OpLt,
263			Dest: cmpTemp,
264			Src1: Operand{Name: iterName},
265			Src2: endOp,
266		})
267	
268		// Jump if false (exit loop)
269		g.emit(Instruction{
270			Op:    OpJumpIfFalse,
271			Src1:  cmpTemp,
272			Label: endLabel,
273		})
274	
275		// Generate body
276		if err := g.genStmt(bodyStmt); err != nil {
277			return err
278		}
279	
280		// Increment iterator
281		incrTemp := g.newTemp()
282		g.emit(Instruction{
283			Op:   OpAdd,
284			Dest: incrTemp,
285			Src1: Operand{Name: iterName},
286			Src2: Operand{IsImm: true, ImmVal: 1},
287		})
288		g.emit(Instruction{
289			Op:   OpCopy,
290			Dest: Operand{Name: iterName},
291			Src1: incrTemp,
292		})
293	
294		// Jump back to loop
295		g.emit(Instruction{
296			Op:    OpJump,
297			Label: loopLabel,
298		})
299	
300		// Emit end label
301		g.emit(Instruction{
302			Op:    OpLabel,
303			Label: endLabel,
304		})
305	
306		return nil
307	}
308	
309	// genReturn generates IR for a return statement
310	func (g *Generator) genReturn(node *ast.Node) error {
311		if len(node.Children) == 0 {
312			g.emit(Instruction{Op: OpReturn})
313			return nil
314		}
315	
316		returnOp, err := g.genExpr(node.Children[0])
317		if err != nil {
318			return err
319		}
320	
321		g.emit(Instruction{
322			Op:   OpReturn,
323			Src1: returnOp,
324		})
325	
326		return nil
327	}
328	
329	// genExpr generates IR for an expression and returns the operand
330	func (g *Generator) genExpr(node *ast.Node) (Operand, error) {
331		if node == nil {
332			return Operand{}, fmt.Errorf("nil expression")
333		}
334	
335		switch node.Kind {
336		case ast.NodeIntLit:
337			// Parse integer literal
338			var val int64
339			fmt.Sscanf(node.Value, "%d", &val)
340			return Operand{IsImm: true, ImmVal: val}, nil
341	
342		case ast.NodeIdent:
343			return Operand{Name: node.Value}, nil
344	
345		case ast.NodeBinaryExpr:
346			return g.genBinaryExpr(node)
347	
348		case ast.NodeCallExpr:
349			return g.genCallExpr(node)
350	
351		case ast.NodeFieldAccess:
352			return g.genFieldAccess(node)
353	
354		default:
355			return Operand{}, fmt.Errorf("unsupported expression kind: %d", node.Kind)
356		}
357	}
358	
359	// genBinaryExpr generates IR for a binary expression
360	func (g *Generator) genBinaryExpr(node *ast.Node) (Operand, error) {
361		if len(node.Children) < 2 {
362			return Operand{}, fmt.Errorf("binary expression requires 2 operands")
363		}
364	
365		left, err := g.genExpr(node.Children[0])
366		if err != nil {
367			return Operand{}, err
368		}
369	
370		right, err := g.genExpr(node.Children[1])
371		if err != nil {
372			return Operand{}, err
373		}
374	
375		result := g.newTemp()
376		op := g.opcodeFromOp(node.Value)
377	
378		g.emit(Instruction{
379			Op:   op,
380			Dest: result,
381			Src1: left,
382			Src2: right,
383		})
384	
385		return result, nil
386	}
387	
388	// genCallExpr generates IR for a function call
389	func (g *Generator) genCallExpr(node *ast.Node) (Operand, error) {
390		if len(node.Children) == 0 {
391			return Operand{}, fmt.Errorf("call expression requires function name")
392		}
393	
394		fnName := node.Children[0].Value
395	
396		// Special handling for syscall
397		if fnName == "syscall" {
398			if len(node.Children) < 2 {
399				return Operand{}, fmt.Errorf("syscall requires at least syscall number")
400			}
401	
402			// syscall number (always first arg after function name)
403			numOp, err := g.genExpr(node.Children[1])
404			if err != nil {
405				return Operand{}, err
406			}
407	
408			// Additional args (starting from index 2)
409			for i := 2; i < len(node.Children); i++ {
410				argOp, err := g.genExpr(node.Children[i])
411				if err != nil {
412					return Operand{}, err
413				}
414				g.emit(Instruction{
415					Op:   OpParam,
416					Src1: argOp,
417				})
418			}
419	
420			// Emit syscall instruction
421			result := g.newTemp()
422			g.emit(Instruction{
423				Op:   OpSyscall,
424				Dest: result,
425				Src1: numOp,
426			})
427	
428			return result, nil
429		}
430	
431		// Emit parameters for regular function calls
432		for i := 1; i < len(node.Children); i++ {
433			argOp, err := g.genExpr(node.Children[i])
434			if err != nil {
435				return Operand{}, err
436			}
437			g.emit(Instruction{
438				Op:   OpParam,
439				Src1: argOp,
440			})
441		}
442	
443		// Emit call
444		result := g.newTemp()
445		g.emit(Instruction{
446			Op:   OpCall,
447			Dest: result,
448			Fn:   fnName,
449		})
450	
451		return result, nil
452	}
453	
454	// Helper functions
455	
456	func (g *Generator) newTemp() Operand {
457		temp := Operand{
458			IsTemp: true,
459			Name:   fmt.Sprintf("t%d", g.tempCount),
460		}
461		g.tempCount++
462		return temp
463	}
464	
465	func (g *Generator) newLabel(prefix string) string {
466		label := fmt.Sprintf("L_%s_%d", prefix, g.labelCount)
467		g.labelCount++
468		return label
469	}
470	
471	func (g *Generator) emit(instr Instruction) {
472		if g.currentFn != nil {
473			g.currentFn.Body = append(g.currentFn.Body, instr)
474		} else {
475			g.program.Main = append(g.program.Main, instr)
476		}
477	}
478	
479	func (g *Generator) opcodeFromOp(op string) Opcode {
480		switch op {
481		case "+":
482			return OpAdd
483		case "-":
484			return OpSub
485		case "*":
486			return OpMul
487		case "/":
488			return OpDiv
489		case "==":
490			return OpEq
491		case "!=":
492			return OpNe
493		case "<":
494			return OpLt
495		case ">":
496			return OpGt
497		case "<=":
498			return OpLe
499		case ">=":
500			return OpGe
501		default:
502			return OpNoop
503		}
504	}
505	
506	// genStructDecl generates IR for a struct declaration
507	func (g *Generator) genStructDecl(node *ast.Node) error {
508		if node.Value == "" {
509			return fmt.Errorf("struct declaration must have a name")
510		}
511	
512		name := node.Value
513		fields := []string{}
514	
515		// Extract field names from children
516		for _, field := range node.Children {
517			if field.Kind == ast.NodeFieldDecl {
518				fields = append(fields, field.Value)
519			}
520		}
521	
522		// Store struct definition
523		g.structFields[name] = fields
524	
525		// Calculate struct size (8 bytes per field)
526		size := len(fields) * 8
527	
528		// Save current function context
529		prevFn := g.currentFn
530		g.currentFn = nil // Emit to Main context
531	
532		// Emit OpStructDef instruction
533		g.emit(Instruction{
534			Op:   OpStructDef,
535			Fn:   name,
536			Src1: Operand{IsImm: true, ImmVal: int64(size)},
537		})
538	
539		// Restore function context
540		g.currentFn = prevFn
541	
542		return nil
543	}
544	
545	// genFieldAccess generates IR for a field access expression (obj.field)
546	func (g *Generator) genFieldAccess(node *ast.Node) (Operand, error) {
547		if len(node.Children) == 0 {
548			return Operand{}, fmt.Errorf("field access requires object expression")
549		}
550	
551		// Generate IR for object expression
552		objOp, err := g.genExpr(node.Children[0])
553		if err != nil {
554			return Operand{}, err
555		}
556	
557		fieldName := node.Value
558	
559		// Search for field offset in known structs
560		var offset int64
561		found := false
562		for _, fields := range g.structFields {
563			for i, f := range fields {
564				if f == fieldName {
565					offset = int64(i * 8)
566					found = true
567					break
568				}
569			}
570			if found {
571				break
572			}
573		}
574		// If not found, use offset 0 as fallback
575	
576		// Emit OpFieldLoad instruction
577		result := g.newTemp()
578		g.emit(Instruction{
579			Op:   OpFieldLoad,
580			Dest: result,
581			Src1: objOp,
582			Src2: Operand{IsImm: true, ImmVal: offset},
583		})
584	
585		return result, nil
586	}
